/**
 * Regenerates test/fixtures/structureReplay.json: the structure replay over the
 * first session (header + 390 one-minute rows) of the planted-episode files.
 * One session keeps the recording small enough to read; it is generated by
 * running the engine, never written by hand. `structureReplay.test.ts` fails if
 * this output and the committed file differ.
 *
 *   npx tsx tools/fixtures/structureFixture.ts
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { runStructureReplay } from '../../src/research/structureReplay';
import { stableStringify } from '../../src/research/setupReplay';

export const STRUCTURE_FIXTURE_ROWS = 390;
const FIX = join(__dirname, '..', '..', 'test', 'fixtures');

export function structureFixtureInput(): { config: unknown; csv: Record<string, string> } {
  const slice = (f: string): string => readFileSync(join(FIX, 'bars', f), 'utf8').split('\n').slice(0, STRUCTURE_FIXTURE_ROWS + 1).join('\n') + '\n';
  return {
    config: JSON.parse(readFileSync(join(FIX, 'bars', 'structure.config.json'), 'utf8')),
    csv: { SPY: slice('EPISODE_SPY_1m.csv'), QQQ: slice('EPISODE_QQQ_1m.csv') },
  };
}

export function structureFixtureText(): string {
  return stableStringify(runStructureReplay(structureFixtureInput()));
}

if (require.main === module) writeFileSync(join(FIX, 'structureReplay.json'), structureFixtureText());
